public class CarryingAnimator : MonoBehaviour
{
    [SerializeField] private Transform shoulderJoint;
    [SerializeField] private Transform characterBody;

    void Start()
    {
        // Trigger the carrying state
        StartCoroutine(CarryAction());
    }

    IEnumerator CarryAction()
    {
        // Animation loop
        while (true)
        {
            // Move the shoulder joint
            shoulderJoint.position = Vector3.MoveTowards(transform.position, new Vector3(0, 0, 0), 0.5f);

            // Update character body
